// TMP117 on I2C address 0x48 (ADD0 tied to GND)
const ADDR = 0x48;
log('Device ID =', hex(i2c.readReg16(ADDR, 0x0F)));

delay(200); // first result after a reset takes a while (see the data-ready flag)
const cfg = i2c.readReg16(ADDR, 0x01);
log('Config =', hex(cfg), (cfg & 0x2000) ? '(data ready)' : '(not ready yet)');

const raw = toInt16(i2c.readReg16(ADDR, 0x00));
log('raw =', raw, '->', (raw * 0.0078125).toFixed(4), 'C');
